const fs = require("fs");
const path = require("path");
const discord = require("discord.js");
const childProcess = require("child_process");

const RVC = require('../../../util/rvc');
const TTS = require('../../../util/tts');
const env = require("../../../util/env-util");
const FFmpegUtil = require('../../../util/ffmpeg-util');
const TempFolder = require('../../../util/temp-folder');

class Command {
    constructor(client) {
        this.name = "ttsjeremy";
        this.description = "Jeremy gamer 14 will Text to speech (ai cover of tts)";
        this.attributes = {
            unlisted: true,
            jgAiCoverCommand: true,
            permission: 0,
        };

        this.client = client;

        this.alias = ["jtts", "ttsj", "jeremytts",                       "jspeak", "speakj", "jeremyspeak", "speakjeremy"];
    }

    async handle(message, args, util) {
        const ttsText = args.join(" ");
        if (ttsText.length > 1024) return message.reply("Thats Way too much");
        const ttsBuffer = await TTS.speak(ttsText, "balabolka", "en", "Microsoft David Desktop");

        // actually start doing stuff
        const startTime = Date.now();

        const jobName = TempFolder.makeTempName("ttsjeremy");
        const temporaryFolder = new TempFolder(jobName);
        await temporaryFolder.createAndDestroy(async (tempDir) => {
            // save the buffer somewhere (its probably a small file)
            const ttsInputPath = path.join(tempDir, "tts_normal.mp3");
            fs.writeFileSync(ttsInputPath, ttsBuffer);

            // see if we need approval
            let replyMessage = null;
            const canCheckTestServers = env.getBool("CHECK_FOR_DEFAULT_TEST_SERVERS");
            const wasMessageSentInTestServer = !canCheckTestServers ? false : message.guildId === "746156168560508950";
            if (!wasMessageSentInTestServer) {
                replyMessage = await message.reply("# me and ishowspeed need to approve your TTS"
                    + "\n" + "Please wait for your TTS to be accepted."
                    + "\n" + "- You may be denied if im already processing a TTS (im too lazy to add a real queue thing)"
                    + "\n" + "- You may be denied if im not currently active or the bot is about to shut down for the day"
                    + "\n" + "- Genuinely offensive/inappropriate content will be denied AND result in a **permanent ban** from the server!");

                const requestDetails = `AI TTS cover request`
                    + `\n` + `\`${ttsText.replace(/\n/g, " ")}\``;
                const accepted = await util.requestApproval(replyMessage, message, requestDetails, [ttsInputPath]);
                if (!accepted) return; // rejects will be handled by requestApproval
            }

            // have my AI voice cover it
            // create message if we didnt before
            if (!replyMessage) { replyMessage = await message.reply(`Covering TTS with AI jeremygamer13 (this may take a bit)`); }
            else { await replyMessage.edit(`Covering TTS with AI jeremygamer13 (this may take a bit)`); }
            // ok now do it
            const outputPathAICover = path.join(tempDir, "ai_tts_jeremy_only.mp3");
            await RVC.infer(ttsInputPath, env.get("COVER_PATH_MODEL"), env.get("COVER_PATH_INDEX"), outputPathAICover, "rmvpe", 0);

            // remux the audio to ogg because it might not actually be efficient mp3
            const outputRemuxedPath = path.join(tempDir, `ai_tts_jeremy_remuxed.ogg`);
            await replyMessage.edit(`remuxing audio`);
            await FFmpegUtil.commands.convertToSafeOgg(outputPathAICover, outputRemuxedPath);

            await replyMessage.edit({
                content: "Completed in " + ((Date.now() - startTime) / 1000) + " seconds"
                    + "\n" + `-# Generated by <@${message.author.id}>`,
                files: [outputRemuxedPath]
            });
        });
    }
    async invoke(message, args, util) {
        if (!env.getBool("RVC_ENABLED")) throw new Error("RVC is disabled on this system");
        const canDo = util.request("heavyExternalStuff");
        if (!canDo) return message.reply("disabled (im probably playing a game)");

        await this.handle(message, args, util);
    }
}

// needs to do new Command() in index.js because typing static every time STINKS!
module.exports = Command;